<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetVisibilityService;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetReadGateway;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetFilter;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetCursor;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetVisibilityService $visibility,
        private readonly SnippetReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Snippet");
        $span = $this->startSpan("Check allow of list usecase for Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(SnippetFilter $filter): int
    {
        $this->logDebug("Run list usecase for Snippet");
        $span = $this->startSpan("Run list usecase for Snippet");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Snippet');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(SnippetFilter $filter, ?SnippetCursor $cursor = null): SnippetAttributesSlide
    {
        $this->logDebug("Run list usecase for Snippet");
        $span = $this->startSpan("Run list usecase for Snippet");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new SnippetAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
